// ball touches (by overlap or by sweep) and applies the bounce exactly once,
// on the brick with the smallest penetration (the face most decisively hit),
// so a seam overlapping two bricks in the same pass cannot flip the same
// component twice. Returns the number of bricks broken.
export function brickHit(prevX, prevY, ball, bricks) {
  let best = null;        // overlapping brick with the smallest penetration
  let bestPen = Infinity;
  let swept = [];         // bricks crossed without overlapping at the end

  for (const brick of bricks) {
    if (!brick.alive) continue;

