// --- #1: brick bounce (regression suite for the plow-through bug) ----------
// Helpers: a live brick and a ball (with a previous position for the sweep).
function brick(x, y, w = 72, h = 20) {
  return { x, y, w, h, alive: true };
}

function ball(x, y, vx = 0, vy = 0, r = 7) {
  return { x, y, r, vx, vy };
}

test('brickHit: head-on top hit flips vy and pushes the ball out', () => {
  const b = brick(100, 100);
  const b1 = ball(136, 112, 0, 300); // moving down, 5px into the brick
  const broken = brickHit(136, 100, b1, [b]);
  assert.equal(broken, 1);
  assert.ok(b1.vy < 0, 'vy flips upward on a top hit');
  assert.equal(b1.vx, 0, 'vx is left untouched');
  assert.equal(b1.y, 100 - b1.r, 'ball pushed out above the brick');
  assert.equal(collides(b1, b), false, 'ball no longer overlaps the brick');
});

test('brickHit: side hit flips vx and pushes the ball out', () => {
  const b = brick(100, 100);
  const b1 = ball(112, 110, 300, 0); // moving right, 5px into the left face
