// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit — `bounceOffBrick()` answers that from the penetration.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// True if the ball swept from (prevX, prevY) to its CURRENT position crossed
// the brick's box grown by the ball radius. Returns { axis, tEnter } (the
// face axis hit first and when, in 0..1) or null when the path misses.
// This catches tunnelling: at level 6 the ball moves up to 35.5 px per frame
// against a 34 px brick+ball thickness, so it can jump over a brick without
// ever overlapping it (a discrete test at the two endpoints sees nothing).
export function sweepHitsBrick(prevX, prevY, ball, brick) {
  const minX = brick.x - ball.r;
  const maxX = brick.x + brick.w + ball.r;
  const minY = brick.y - ball.r;
  const maxY = brick.y + brick.h + ball.r;

  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  // Slab method: find the t-interval of the move spent inside each axis
  // slab; the intersection of both intervals is the time inside the box.
  let tEnter = 0;
  let tExit = 1;
  let axis = null;

  if (dx === 0) {
    if (prevX <= minX || prevX >= maxX) return null;
  } else {
    let t1 = (minX - prevX) / dx;
    let t2 = (maxX - prevX) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tEnter) {
      tEnter = t1;
      axis = 'x';
    }
    if (t2 < tExit) tExit = t2;
    if (tEnter > tExit) return null;
  }

  if (dy === 0) {
    if (prevY <= minY || prevY >= maxY) return null;
  } else {
    let t1 = (minY - prevY) / dy;
    let t2 = (maxY - prevY) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t1 > tEnter) {
      tEnter = t1;
      axis = 'y';
    }
    if (t2 < tExit) tExit = t2;
    if (tEnter > tExit) return null;
  }

  // The crossing must happen strictly inside the move: a path that only
  // touches the box at its endpoints, or starts inside it, is the per-frame
  // overlap case handled by `collides()` instead.
  if (tEnter >= 1 || tExit <= 0) return null;
  return { axis, tEnter };
}

// Bounces on X if the ball is moving INTO the face it overlaps. The
// direction check is what makes the bounce idempotent: a seam overlapping two
// bricks in the same pass cannot flip the same component twice (vy = -vy
// twice cancels out and the ball would go straight through). Returns true
// when a bounce was applied.
function bounceAxisX(ball, brick, penLeft, penRight) {
  if (penLeft <= penRight) {
    // Near the brick's left face.
    if (ball.vx > 0) {
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x - ball.r;
      return true;
    }
  } else if (ball.vx < 0) {
    // Near the brick's right face.
    ball.vx = Math.abs(ball.vx);
    ball.x = brick.x + brick.w + ball.r;
    return true;
  }
  return false;
}

function bounceAxisY(ball, brick, penTop, penBottom) {
  if (penTop <= penBottom) {
    // Near the brick's top face.
    if (ball.vy > 0) {
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y - ball.r;
      return true;
    }
  } else if (ball.vy < 0) {
    // Near the brick's bottom face.
    ball.vy = Math.abs(ball.vy);
    ball.y = brick.y + brick.h + ball.r;
    return true;
  }
  return false;
}

// Applies a single bounce against one overlapping brick: the axis with the
// smaller penetration is the face that was hit (both on a corner hit). The
// ball is pushed back OUT of the brick, otherwise it still overlaps on the
// next frame and re-flips forever (sticky bounce). If the ball is moving away
// from the shallowest face (it is leaving the brick through a seam), fall
// through to the other axis instead of letting it pass unchecked.
function bounceOffBrick(ball, brick) {
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);

  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  if (penX < penY) {
    if (!bounceAxisX(ball, brick, penLeft, penRight)) {
      bounceAxisY(ball, brick, penTop, penBottom);
    }
  } else if (penY < penX) {
    if (!bounceAxisY(ball, brick, penTop, penBottom)) {
      bounceAxisX(ball, brick, penLeft, penRight);
    }
  } else {
    // Corner: equal penetrations mean a diagonal hit — flip both components.
    bounceAxisX(ball, brick, penLeft, penRight);
    bounceAxisY(ball, brick, penTop, penBottom);
  }
}

// Bounces a ball that tunnelled THROUGH a brick: it crossed the whole brick
// in one frame and ended past it, so it never overlapped the brick at its
// final position. Flip the component of the face it crossed and put the ball
// back on the entry side of that face (its velocity points back the way it
// came, so the face is simply the side it approached from).
function bounceSwept(ball, brick, axis) {
  if (axis === 'x') {
    if (ball.vx > 0) {
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x - ball.r;
    } else {
      ball.vx = Math.abs(ball.vx);
      ball.x = brick.x + brick.w + ball.r;
    }
  } else {
    if (ball.vy > 0) {
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y - ball.r;
    } else {
      ball.vy = Math.abs(ball.vy);
      ball.y = brick.y + brick.h + ball.r;
    }
  }
}

// Resolves the ball against every brick for one frame (pure, tested).
//  1. Breaks every brick the ball touches, whether by final overlap or by a
//     sweep across the move (tunnelling).
//  2. Applies the bounce EXACTLY ONCE, on the brick with the smallest
//     penetration (the face most decisively hit), so a seam overlapping two
//     bricks in the same pass cannot flip the same component twice.
// Returns the number of bricks broken.
export function brickHit(prevX, prevY, ball, bricks) {
  let broken = 0;
  let best = null; // overlapping brick with the smallest penetration
  let bestPen = Infinity;
  let firstSwept = null; // brick crossed first by the sweep

  for (const brick of bricks) {
    if (!brick.alive) continue;

    if (collides(ball, brick)) {
      brick.alive = false;
      broken += 1;
      const penLeft = ball.x + ball.r - brick.x;
      const penRight = brick.x + brick.w - (ball.x - ball.r);
      const penTop = ball.y + ball.r - brick.y;
      const penBottom = brick.y + brick.h - (ball.y - ball.r);
      const pen = Math.min(Math.min(penLeft, penRight), Math.min(penTop, penBottom));
      if (pen < bestPen) {
        bestPen = pen;
        best = brick;
      }
    } else {
      const hit = sweepHitsBrick(prevX, prevY, ball, brick);
      if (hit) {
        brick.alive = false;
        broken += 1;
        if (!firstSwept || hit.tEnter < firstSwept.tEnter) {
          firstSwept = { brick, tEnter: hit.tEnter, axis: hit.axis };
        }
      }
    }
  }

  if (best) {
    bounceOffBrick(ball, best);
  } else if (firstSwept) {
    bounceSwept(ball, firstSwept.brick, firstSwept.axis);
  }

  return broken;
}

