export function step(state, dt) {
  const { ball, paddle } = state;

  // Record where the ball was BEFORE this move so the brick collision sweep
  // (`brickHit`) can detect tunnelling between the two positions.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

