// Main render loop. The collision resolution itself lives in the pure,
// tested `brickHit()`; `frame()` only calls it and draws (ISSUES.md #2).
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: resolve collisions (bounce + break + score), then draw.
  const broken = brickHit(
    state.ball.px ?? state.ball.x,
    state.ball.py ?? state.ball.y,
    state.ball,
    state.bricks,
  );
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  if (broken > 0) {
    state.combo += broken;
    // Score is awarded for the whole group of bricks broken in this pass;
    // the combo grows by one per brick, matching the old per-brick loop.
    for (let i = 0; i < broken; i += 1) {
      state.score += scoreForBrick(state.bricks[i], state.combo);
    }
  }

