test('brickHit: head-on top hit flips vy and pushes the ball out', () => {
  const b = brick(100, 100);
  const b1 = ball(136, 103, 0, 300); // moving down, 10px into the brick
  const broken = brickHit(136, 100, b1, [b]);
  assert.equal(broken.length, 1);
  assert.ok(b1.vy < 0, 'vy flips upward on a top hit');
  assert.equal(b1.vx, 0, 'vx is left untouched');
  assert.equal(b1.y, 100 - b1.r, 'ball pushed out above the brick');
  assert.equal(collides(b1, b), false, 'ball no longer overlaps the brick');
});

test('brickHit: deep penetration (stutter frame) still bounces back', () => {
  // A dropped frame at level 6 can move the ball 35px in one step: it ends
  // DEEP inside the brick (bottom face is nearer than the top) and no face
  // check alone applies — the ball must still bounce back, not plow through.
  const b = brick(100, 100);
  const b1 = ball(136, 112, 0, 710); // 19px deep: penBottom 15 < penTop 19
  const broken = brickHit(136, 76, b1, [b]);
  assert.equal(broken.length, 1);
  assert.ok(b1.vy < 0, 'vy flips upward');
  assert.equal(b1.y, 100 - b1.r);
  assert.equal(collides(b1, b), false);
});

